<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue'
import Icon from './Icon.vue'
import { theme, setTheme } from '../theme'
import { request, roleName, type Row } from '../business'
import { tokenKey } from '../auth'
import { useOverlayScrollLock } from '../composables/useOverlayScrollLock'
const props=defineProps<{profile:Row;areas:Row[];readonly?:boolean;activeTab?:string}>()
const emit=defineEmits<{updated:[value:Row];notify:[message:string];tab:[value:string]}>()
const active=ref('基本信息'),draft=ref<Row>({}),saving=ref(false),error=ref(''),sessions=ref<Row[]>([]),avatarInput=ref<HTMLInputElement|null>(null),avatarUrl=ref(''),phoneVisible=ref(false),password=ref<Row|null>(null)
useOverlayScrollLock(()=>!!password.value)
const tabs=[{name:'基本信息',icon:'user'},{name:'安全设置',icon:'check'},{name:'通知偏好',icon:'bell'},{name:'登录设备',icon:'grid'},{name:'外观设置',icon:'eye'}]
function reset(){draft.value={...props.profile,preferences:{sound:true,desktop:false,criticalOnly:false,quietStart:'22:00',quietEnd:'07:00',...props.profile.preferences}}}
watch(()=>props.profile,reset,{immediate:true})
watch(()=>props.activeTab,value=>{if(value)active.value=value},{immediate:true})
watch(active,value=>emit('tab',value))
async function save(message='个人资料已保存'){if(props.readonly||saving.value)return;saving.value=true;error.value='';try{await request('/profile','PUT',draft.value);const result=await request<Row>('/profile');emit('updated',result);emit('notify',message)}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
async function devices(){try{sessions.value=await request('/sessions')}catch(e){error.value=e instanceof Error?e.message:'无法读取登录设备'}}
async function revoke(id?:string){saving.value=true;error.value='';try{await request(id?`/sessions/${id}/revoke`:'/sessions/revoke-others','POST');await devices();emit('notify',id?'设备已下线':'其他设备已全部下线')}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{saving.value=false}}
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file||props.readonly)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024){error.value='头像须为5MB以内的JPG或PNG';return}saving.value=true;error.value='';try{if(!sessionStorage.getItem('nephh-demo')){const data=new FormData();data.append('file',file);await request('/profile/avatar','POST',data)}if(avatarUrl.value)URL.revokeObjectURL(avatarUrl.value);avatarUrl.value=URL.createObjectURL(file);emit('updated',{...props.profile,avatar:true,avatarBlob:avatarUrl.value});emit('notify','头像已更新')}catch(err){error.value=err instanceof Error?err.message:'上传失败'}finally{saving.value=false}}
async function changePassword(){if(!password.value)return;if(password.value.newPassword!==password.value.confirmPassword){error.value='两次输入的新密码不一致';return}saving.value=true;error.value='';try{await request('/profile/password','POST',password.value);password.value=null;emit('notify','密码已修改，其他设备已下线')}catch(e){error.value=e instanceof Error?e.message:'修改失败'}finally{saving.value=false}}
async function preference(key:string){
 if(key==='desktop'&&!draft.value.preferences.desktop&&!sessionStorage.getItem('nephh-demo')){
  if(!('Notification' in window)){error.value='当前浏览器不支持桌面通知';return}
  try{if(await Notification.requestPermission()!=='granted'){error.value='桌面通知未获授权，请在浏览器设置中允许后重试';return}}catch{error.value='当前环境无法开启桌面通知';return}
 }
 draft.value.preferences[key]=!draft.value.preferences[key];await save('通知偏好已保存')
}
function mask(value:string){return value?.length>=7?value.slice(0,3)+'****'+value.slice(-4):value||''}
function time(value:any){if(!value)return '—';const d=new Date(value),minutes=Math.floor((Date.now()-d.getTime())/60000);if(minutes<1)return '刚刚';if(minutes<60)return minutes+'分钟前';if(minutes<1440)return Math.floor(minutes/60)+'小时前';const yesterday=new Date(Date.now()-86400000);return (d.toDateString()===yesterday.toDateString()?'昨天 ':d.toLocaleDateString('zh-CN')+' ')+d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
onMounted(async()=>{await devices();if(props.profile.avatarBlob)avatarUrl.value=props.profile.avatarBlob;else if(props.profile.avatar&&!sessionStorage.getItem('nephh-demo'))try{const r=await fetch('/api/business/profile/avatar',{headers:{Authorization:'Bearer '+sessionStorage.getItem(tokenKey)}});if(r.ok)avatarUrl.value=URL.createObjectURL(await r.blob())}catch{}})
onUnmounted(()=>{if(avatarUrl.value)URL.revokeObjectURL(avatarUrl.value)})
</script>
<template>
<div class="d-settings-layout"><nav class="d-settings-nav"><small>账号设置</small><button v-for="t in tabs" :class="{selected:active===t.name}" @click="active=t.name;error=''" :aria-label="t.name"><Icon :name="t.icon"/>{{t.name}}</button></nav><section class="d-settings-card" :class="{basic:active==='基本信息'}"><header><div><h2>{{active}}</h2><p>{{active==='基本信息'?'管理账号资料与组织信息':active==='安全设置'?'管理密码、验证方式与会话安全':active==='通知偏好'?'控制告警提醒方式与接收范围':active==='外观设置'?'选择适合当前环境的界面主题':'管理当前账号已登录的设备'}}</p></div><button v-if="active==='登录设备'" class="d-link red" :disabled="saving||readonly" @click="revoke()">全部下线</button></header><p v-if="error&&!password" class="d-error" role="alert">{{error}}</p>
<template v-if="active==='基本信息'"><div class="d-profile-avatar"><span class="d-avatar large"><img v-if="avatarUrl" :src="avatarUrl" alt="个人头像"/><template v-else>{{(draft.displayName||draft.username||'用').slice(0,1)}}</template></span><div><b>个人头像</b><p>支持 JPG、PNG，文件不超过 5 MB</p><button class="d-link teal" :disabled="saving||readonly" @click="avatarInput?.click()">更换头像</button><input ref="avatarInput" type="file" accept="image/png,image/jpeg" hidden @change="upload"/></div></div><form class="d-profile-form" @submit.prevent="save()"><div class="d-form-grid"><label>姓名<input v-model="draft.displayName" maxlength="100" required :disabled="readonly"/></label><label>工号<input :value="draft.username" disabled/></label><label>角色<select disabled :value="draft.role"><option :value="draft.role">{{roleName[draft.role]||'当前角色'}}</option></select></label><label>所属区域<select v-model="draft.areaId" :disabled="readonly"><option :value="null">未设置</option><option v-for="a in areas" :value="a.id">{{a.name}}</option></select></label><label>手机<div class="d-profile-phone"><input :value="phoneVisible?draft.phone:mask(draft.phone)" :disabled="readonly" @focus="phoneVisible=true" @input="draft.phone=($event.target as HTMLInputElement).value" maxlength="32"/><button type="button" class="d-link teal" :disabled="readonly" @click="phoneVisible=true">换绑</button></div></label><label>邮箱<input v-model="draft.email" type="email" maxlength="200" :disabled="readonly"/></label></div><footer><small><Icon name="warning"/>修改会同步至本地及个人审计日志</small><div><button type="button" :disabled="saving" @click="reset">取消</button><button class="primary" :disabled="saving||readonly">保存修改</button></div></footer></form></template>
<template v-else-if="active==='外观设置'"><div class="d-settings-row"><div><b>昼夜模式</b><small>切换界面明暗，自动记住本机选择</small></div></div><div class="d-theme-options" role="group" aria-label="昼夜模式"><button type="button" :class="{selected:theme==='light'}" :aria-pressed="theme==='light'" @click="setTheme('light')"><span class="d-theme-swatch light"></span><b>日间模式</b><small>浅色背景，适合明亮环境</small></button><button type="button" :class="{selected:theme==='dark'}" :aria-pressed="theme==='dark'" @click="setTheme('dark')"><span class="d-theme-swatch dark"></span><b>夜间模式</b><small>深色背景，适合低光环境</small></button></div></template><template v-else-if="active==='安全设置'"><div class="d-security-row"><i class="d-settings-icon"><Icon name="edit"/></i><div><b>修改密码</b><small>建议每90天更新一次密码</small></div><button class="d-link push" :disabled="readonly" @click="password={currentPassword:'',newPassword:'',confirmPassword:''};error=''">修改 <Icon name="arrow"/></button></div><div class="d-settings-row"><div><b>二次验证</b><small>尚未配置验证服务</small></div><button class="d-switch" role="switch" aria-label="二次验证（尚未配置）" :aria-checked="false" disabled title="验证服务尚未接入"><i></i></button></div><div class="d-settings-row"><div><b>会话超时</b><small>无操作后自动退出登录</small></div><select v-model.number="draft.idleMinutes" :disabled="saving||readonly" @change="save('会话超时设置已保存')"><option :value="15">15分钟</option><option :value="30">30分钟</option><option :value="60">60分钟</option></select></div></template>
<template v-else-if="active==='通知偏好'"><div v-for="item in [{key:'sound',name:'告警声音',sub:'新告警到达时播放提示音'},{key:'desktop',name:'桌面推送',sub:'允许浏览器发送系统通知'},{key:'criticalOnly',name:'只看高危告警',sub:'开启后仅接收高风险与需处置级别'}]" class="d-settings-row"><div><b>{{item.name}}</b><small>{{item.sub}}</small></div><button class="d-switch" :class="{on:draft.preferences?.[item.key]}" role="switch" :aria-label="item.name" :aria-checked="!!draft.preferences?.[item.key]" :disabled="saving||readonly" @click="preference(item.key)"><i></i></button></div><div class="d-settings-row"><div><b>免打扰时段</b><small>该时段内仅推送高危告警</small></div><div class="d-quiet-time"><input v-model="draft.preferences.quietStart" type="time" aria-label="免打扰开始时间" :disabled="saving||readonly" @change="save('免打扰时段已保存')"/><span>—</span><input v-model="draft.preferences.quietEnd" type="time" aria-label="免打扰结束时间" :disabled="saving||readonly" @change="save('免打扰时段已保存')"/></div></div></template>
<template v-else><div v-for="s in sessions" class="d-device-row"><i class="d-settings-icon"><Icon :name="/iPhone|iPad|Android|HarmonyOS/i.test(s.platform||'')?'phone':'desktop'"/></i><div><b>{{s.browser}} · {{s.platform}}</b><small>{{s.location||'连接地址'}} · {{s.ip}}</small></div><div class="push"><small>最近活跃</small><span>{{s.current?'刚刚':time(s.lastSeen)}}</span></div><span v-if="s.current" class="d-pill teal">当前设备</span><button v-else class="d-link red" :disabled="saving||readonly" @click="revoke(s.id)">下线</button></div><p v-if="!sessions.length" class="work-empty">没有其他已登录设备</p></template>
</section></div>
<div v-if="password" class="work-overlay d-password-overlay" @click.self="!saving&&(password=null)"><form class="d-password-modal" @submit.prevent="changePassword"><header><div><span class="eyebrow">安全验证</span><h2>修改密码</h2></div><button type="button" aria-label="关闭修改密码" :disabled="saving" @click="password=null;error=''"><Icon name="close"/></button></header><div><label>当前密码<input v-model="password.currentPassword" type="password" placeholder="请输入当前密码" autocomplete="current-password" required/></label><label>新密码<input v-model="password.newPassword" type="password" placeholder="至少8位，包含字母与数字" autocomplete="new-password" minlength="8" required/></label><label>确认新密码<input v-model="password.confirmPassword" type="password" placeholder="再次输入新密码" autocomplete="new-password" required/></label><p v-if="error" class="d-error" role="alert">{{error}}</p></div><footer><button type="button" :disabled="saving" @click="password=null;error=''">取消</button><button class="primary" :disabled="saving">确认修改</button></footer></form></div>
</template>
